def run(actions, tools, max_steps=3):
    if max_steps < 1:
        raise ValueError('max_steps must be positive')
    trace = []
    for step, action in enumerate(actions[:max_steps], start=1):
        name = action['name']
        if name not in tools:
            raise PermissionError('tool is not allow-listed')
        observation = tools[name](**action['arguments'])
        trace.append({'step': step, 'tool': name, 'observation': observation})
    return trace
